import {
  integer,
  pgTable,
  serial,
  text,
  timestamp,
} from "drizzle-orm/pg-core";

// Re-export the Better Auth tables (generated by `bun x auth generate`).
export * from "./auth-schema";

/**
 * A single raffle ticket. Numbers are 1..N (see RAFFLE.totalTickets).
 *
 * status:
 *  - available → for sale (userId = null)
 *  - reserved  → locked by a user who created a payment but it's not paid yet
 *  - paid      → confirmed by an admin
 */
export const tickets = pgTable("tickets", {
  id: serial("id").primaryKey(),
  number: integer("number").notNull(),
  userId: text("user_id"),
  paymentId: integer("payment_id"),
  status: text("status").notNull().default("available"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  paidAt: timestamp("paid_at"),
});

/**
 * A purchase/order of one or more tickets (paid in cash).
 *
 * status:
 *  - pending    → created; awaits admin confirmation
 *  - paid       → confirmed by an admin; tickets marked as paid
 *  - cancelled  → released; tickets freed
 */
export const payments = pgTable("payments", {
  id: serial("id").primaryKey(),
  userId: text("user_id").notNull(),
  method: text("method").notNull(), // cash
  amountMxn: integer("amount_mxn").notNull(),
  status: text("status").notNull().default("pending"),
  adminNote: text("admin_note"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
  confirmedAt: timestamp("confirmed_at"),
  confirmedBy: text("confirmed_by"),
});

export type TicketRow = typeof tickets.$inferSelect;
export type PaymentRow = typeof payments.$inferSelect;